-- =====================================================================
-- Helper Academy — v7: real lyric timings for the Unit 5 songs
-- The subtitle times inside the song files were evenly spaced estimates (3-18 s off).
-- These were measured from the singing: vocals separated with Demucs, words timed with Whisper
-- (both on fal.ai), then matched to the lyric lines. Safe to run more than once.
-- =====================================================================
update public.set_songs set lines = '[{"t": 13.28, "e": 17.86, "l": "Shh... listen close! What''s that sound in the trees?"}, {"t": 17.86, "e": 22.74, "l": "Swish-swish... swish-swish..."}, {"t": 22.74, "e": 26.6, "l": "That''s Rustled! R-U-S-T-L-E-D!"}, {"t": 26.6, "e": 29.78, "l": "What does it mean? Tell me, please!"}, {"t": 29.78, "e": 36.78, "l": "It means making a soft swishing sound! Like dry leaves blowing around!"}, {"t": 36.78, "e": 41.76, "l": "Hhhhhh... phew! That is a Sigh! S-I-G-H!"}, {"t": 41.76, "e": 48.24, "l": "An audible sound made when exhaling in relief!"}, {"t": 48.24, "e": 54.24, "l": "Sway... sway... left and right!"}, {"t": 54.24, "e": 59.82, "l": "Swayed! S-W-A-Y-E-D!"}, {"t": 59.82, "e": 65.92, "l": "Moved from side to side with all its might!"}, {"t": 65.92, "e": 71.8, "l": "Uh oh, uh oh! I''m standing up high! This is Precarious! Oh my, oh my!"}, {"t": 71.8, "e": 83.36, "l": "Let''s spell it out: P-R-E-C-A-R-I-O-U-S!"}, {"t": 83.36, "e": 91.66, "l": "Dangerous or hazardous! Like a leaf on a twig—oh, it''s perilous!"}, {"t": 91.66, "e": 98.44, "l": "Way, way, way out across the sea..."}, {"t": 98.44, "e": 101.28, "l": "Faraway! F-A-R-A-W-A-Y!"}, {"t": 101.28, "e": 108.02, "l": "Very far away; distant, you see!"}, {"t": 108.02, "e": 110.68, "l": "Peek-a-boo! I see you!"}, {"t": 110.68, "e": 113.86, "l": "Observed! O-B-S-E-R-V-E-D!"}, {"t": 113.86, "e": 119.62, "l": "Saw or noticed by watching carefully!"}, {"t": 119.62, "e": 125.94, "l": "One on this side, one on that! Separated! Just like that!"}, {"t": 125.94, "e": 131.64, "l": "S-E-P-A-R-A-T-E-D!"}, {"t": 131.64, "e": 135.98, "l": "Divided into parts or moved apart, agreed!"}, {"t": 135.98, "e": 142.92, "l": "And finally... what does this golden color prize?"}, {"t": 142.92, "e": 149.8, "l": "Symbolized! S-Y-M-B-O-L-I-Z-E-D!"}, {"t": 149.8, "e": 155.76, "l": "S-Y-M-B-O-L-I-Z-E-D!"}, {"t": 155.76, "e": 167.6, "l": "Stood for or represented an idea, feeling, or quality!"}, {"t": 167.6, "e": 177.9, "l": "Spell it! Say it! Know what it means!"}]'::jsonb where id = '00000000-0000-4000-8000-0000000005b1';
update public.set_songs set lines = '[{"t": 2.29, "e": 4.11, "l": "Welcome class to the vocabulary beat"}, {"t": 4.11, "e": 5.99, "l": "Get ready to repeat"}, {"t": 5.99, "e": 8.99, "l": "Let''s spell it out and make it stick"}, {"t": 8.99, "e": 11.21, "l": "Learning these words is a clever trick"}, {"t": 11.21, "e": 13.49, "l": "Spell rustled with me R U S T L E D"}, {"t": 13.49, "e": 15.75, "l": "R U S T L E D that''s how it''s done you see"}, {"t": 15.75, "e": 18.04, "l": "The wind blew the trees and they made a soft sound"}, {"t": 18.04, "e": 20.14, "l": "The dry yellow leaves fell right down to the ground"}, {"t": 20.14, "e": 22.98, "l": "Spell sigh with a breath S I G H my friend"}, {"t": 22.98, "e": 24.84, "l": "S I G H a feeling when things start to end"}, {"t": 24.84, "e": 27.2, "l": "The test is all over she let out a sigh"}, {"t": 27.2, "e": 30.46, "l": "A sound of relief as the clouds drifted by"}, {"t": 30.46, "e": 31.86, "l": "Rustled is a soft sound"}, {"t": 31.86, "e": 34.36, "l": "Sigh is a breath we find"}, {"t": 34.36, "e": 36.2, "l": "Swayed means to move side to side"}, {"t": 36.2, "e": 38.58, "l": "Keep these great words on your mind"}, {"t": 38.58, "e": 40.78, "l": "We are building up our brain"}, {"t": 40.78, "e": 43.08, "l": "Learning words is not in vain"}, {"t": 43.08, "e": 45.4, "l": "Speak them loud and speak them proud"}, {"t": 45.4, "e": 48.22, "l": "Sing them to the whole big crowd"}, {"t": 48.22, "e": 51.04, "l": "Precarious is tricky let''s spell it out loud"}, {"t": 51.04, "e": 53.86, "l": "P R E C A R I O U S we make ourselves proud"}, {"t": 53.86, "e": 56.68, "l": "It''s dangerous and risky a difficult spot"}, {"t": 56.68, "e": 59.5, "l": "Like a leaf on a branch that could easily drop"}, {"t": 59.5, "e": 62.32, "l": "Now faraway places are F A R A W A Y"}, {"t": 62.32, "e": 63.66, "l": "A long distance off where we might want to play"}, {"t": 63.66, "e": 66.02, "l": "The leaf dreamed of places across the blue sea"}, {"t": 66.02, "e": 68.26, "l": "A faraway land where it wanted to be"}, {"t": 68.26, "e": 71.06, "l": "Precarious means risky and bold"}, {"t": 71.06, "e": 73.46, "l": "Faraway is a story untold"}, {"t": 73.46, "e": 75.02, "l": "Observed means to look very close"}, {"t": 75.02, "e": 77.3, "l": "That is the word we will use the most"}, {"t": 77.3, "e": 79.56, "l": "We are building up our brain"}, {"t": 79.56, "e": 81.8, "l": "Learning words is not in vain"}, {"t": 81.8, "e": 86.76, "l": "Speak them loud and speak them proud"}, {"t": 86.76, "e": 89.48, "l": "Sing them to the whole big crowd"}, {"t": 89.48, "e": 91.18, "l": "Observed means to watch let us spell it today"}, {"t": 91.18, "e": 93.76, "l": "O B S E R V E D let us see what you say"}, {"t": 93.76, "e": 95.98, "l": "She noticed the changes so carefully clear"}, {"t": 95.98, "e": 97.8, "l": "As winter was slowly and steadily near"}, {"t": 97.8, "e": 100.32, "l": "Now separated is hard S E P A R A T E D"}, {"t": 100.32, "e": 102.42, "l": "The parts moved apart that was what we just read"}, {"t": 102.42, "e": 104.74, "l": "The leaf and the twig are no longer a pair"}, {"t": 104.74, "e": 107.82, "l": "They separated and flew in the air"}, {"t": 107.82, "e": 116.86, "l": "(Take a breath and listen close)"}, {"t": 116.86, "e": 119.2, "l": "The last big word is capitalized"}, {"t": 119.2, "e": 122.64, "l": "S Y M B O L I Z E D is how it''s written"}, {"t": 122.64, "e": 124.7, "l": "It stood for a feeling or idea so fitting"}, {"t": 124.7, "e": 127.14, "l": "Like the golden leaf showed joy and peace"}, {"t": 127.14, "e": 129.24, "l": "A symbol that made all the worries cease"}, {"t": 129.24, "e": 131.54, "l": "(Now let''s bring it back for the biggest sound)"}, {"t": 131.54, "e": 134.14, "l": "Put your feet on the ground and get ready to bound"}, {"t": 134.14, "e": 136.9, "l": "Separated means moved apart"}, {"t": 136.9, "e": 138.6, "l": "Symbolized came straight from the heart"}, {"t": 138.6, "e": 141.14, "l": "We know the words and we know what they mean"}, {"t": 141.14, "e": 143.36, "l": "We are the smartest class you have ever seen"}, {"t": 143.36, "e": 145.58, "l": "We are building up our brain"}, {"t": 145.58, "e": 147.84, "l": "Learning words is not in vain"}, {"t": 147.84, "e": 150.36, "l": "Speak them loud and speak them proud"}, {"t": 150.36, "e": 152.11, "l": "Sing them to the whole big crowd"}, {"t": 152.11, "e": 156.55, "l": "Great job today everybody"}, {"t": 156.55, "e": 158.85, "l": "You spelled them all right and with style"}, {"t": 158.85, "e": 160.97, "l": "Keep practicing and keep reading"}, {"t": 160.97, "e": 177.9, "l": "You have made your teacher smile"}]'::jsonb where id = '00000000-0000-4000-8000-0000000005b2';
update public.set_songs set lines = '[{"t": 11.85, "e": 14.97, "l": "Let''s clap it out! Every beat, every word! Ready? Let''s go!"}, {"t": 14.97, "e": 17.88, "l": "Shh... listen close! What''s that sound?"}, {"t": 17.88, "e": 23.54, "l": "It''s the leaves! *Swish-swish... swish-swish...*"}, {"t": 23.54, "e": 27.46, "l": "That''s Rustled! Two beats, clap them out:"}, {"t": 27.46, "e": 29.74, "l": "Rus-tled! R-U-S... T-L-E-D!"}, {"t": 29.74, "e": 32.7, "l": "It means a soft swishing sound!"}, {"t": 32.75, "e": 37.18, "l": "Hhhhhh... phew! That is a Sigh!"}, {"t": 37.18, "e": 41.6, "l": "One beat! Just one! S-I-G-H!"}, {"t": 41.6, "e": 44.76, "l": "A sound of relief when you let it out."}, {"t": 44.76, "e": 50.88, "l": "Sway... sway... left and right!"}, {"t": 50.88, "e": 53.9, "l": "Swayed! One smooth beat! S-W-A-Y-E-D!"}, {"t": 53.9, "e": 59.92, "l": "Moving from side to side with all its might!"}, {"t": 59.92, "e": 62.68, "l": "Uh oh, standing up high! This is Pre-car-i-ous!"}, {"t": 62.68, "e": 65.44, "l": "Four claps, slow: Pre-car-i-ous!"}, {"t": 65.44, "e": 71.64, "l": "P-R-E... C-A-R... I... O-U-S!"}, {"t": 71.64, "e": 74.38, "l": "Dangerous, risky, a tricky spot!"}, {"t": 74.38, "e": 77.8, "l": "Look way out, across the blue sea..."}, {"t": 77.8, "e": 80.62, "l": "Far-a-way! Three beats: Far-a-way!"}, {"t": 80.62, "e": 83.14, "l": "F-A-R... A... W-A-Y!"}, {"t": 83.14, "e": 86.8, "l": "It means very distant, far from here!"}, {"t": 86.8, "e": 89.88, "l": "Peek-a-boo! I see you! Ob-served!"}, {"t": 89.88, "e": 90.5, "l": "Two beats: Ob-served!"}, {"t": 90.5, "e": 93.85, "l": "O-B... S-E-R-V-E-D!"}, {"t": 93.85, "e": 98.51, "l": "To watch very closely, see what you see!"}, {"t": 98.51, "e": 101.61, "l": "We''re clapping the beats, we''re learning the sound!"}, {"t": 101.61, "e": 111.31, "l": "These words are the best ones that we''ve ever found!"}, {"t": 111.31, "e": 113.51, "l": "Let''s keep them all safe in our minds today!"}, {"t": 113.51, "e": 119.81, "l": "Learning is easy when we chant and we play!"}, {"t": 119.81, "e": 123.5, "l": "One on this side, one on that! Sep-a-rat-ed!"}, {"t": 123.5, "e": 125.54, "l": "Four beats: Sep-a-rat-ed!"}, {"t": 125.54, "e": 128.42, "l": "S-E-P... A... R-A-T... E-D!"}, {"t": 128.42, "e": 131.08, "l": "Divided into parts, moved apart!"}, {"t": 131.08, "e": 135.48, "l": "And finally, what does this golden color mean?"}, {"t": 135.48, "e": 137.82, "l": "Sym-bol-ized! Three beats: Sym-bol-ized!"}, {"t": 137.82, "e": 140.04, "l": "S-Y-M... B-O-L... I-Z-E-D!"}, {"t": 140.04, "e": 147.28, "l": "Representing a feeling, a hope, or a dream!"}, {"t": 147.28, "e": 149.7, "l": "Rustled! Sigh! Swayed! And more!"}, {"t": 149.7, "e": 155.8, "l": "These are the words that we now adore!"}, {"t": 155.8, "e": 161.22, "l": "Every syllable, every beat!"}, {"t": 161.22, "e": 168.01, "l": "Making our learning so smooth and so sweet!"}, {"t": 168.01, "e": 169.07, "l": "Spell it!"}, {"t": 169.07, "e": 170.31, "l": "Say it!"}, {"t": 170.31, "e": 171.51, "l": "Know what it means!"}, {"t": 171.51, "e": 177.9, "l": "(Keep on clapping... One... two... three... four...)"}]'::jsonb where id = '00000000-0000-4000-8000-0000000005b3';

